    const mes = (d) => d.slice(0, 7), ms = [...new Set(jr.map((r) => mes(r.d)))].sort().slice(-3), bm = grp(jr, mot);
    const TM = [...bm].map(([n, x]) => { const c = ms.map((m) => x.filter((r) => mes(r.d) === m).length); return { n, resp: resp(x[0]), c, d: ms.length > 1 ? c[c.length - 1] - c[c.length - 2] : 0 }; }).sort((a, b) => b.c[b.c.length - 1] - a.c[a.c.length - 1] || b.d - a.d).slice(0, 20);
    const RM = new Map(); jr.forEach((r) => { const k = r.cli + '|' + mot(r), o = RM.get(k) || { cli: r.cli, cn: r.cn, mot: mot(r), ecm: r.ecm, n: 0 }; o.n++; RM.set(k, o); });
