    const dl = (d) => (d > 0 ? `<b style="color:var(--cP)">▲ ${d}</b>` : d < 0 ? `<b style="color:var(--cE)">▼ ${-d}</b>` : '<span class="mu">=</span>');
    if (!jr.length) return '<div class="card"><h3>Sin justificaciones en estos filtros</h3><p>Asigna motivos en «Registro y justificación» para ver el análisis.</p></div>';
    const k80 = M.filter((m, i) => i === 0 || M[i - 1].acu < 80).length;
    const pareto = `<svg class="ch" viewBox="0 0 560 240" role="img" aria-label="Pareto de motivos">${(() => { const top = M.slice(0, 10), mx = Math.max(...top.map((m) => m.t), 1), w = 520 / top.length; return '<line x1="30" y1="190" x2="550" y2="190" stroke="var(--line)"/>' + top.map((m, i) => { const h = (m.t / mx) * 150, x = 34 + i * w; return `<rect x="${x}" y="${190 - h}" width="${w * 0.6}" height="${h}" rx="3" fill="${MCOL(m.resp)}"><title>${esc(m.n)}: ${m.t} (${f1(m.acu)} acum.)</title></rect><text x="${x + w * 0.3}" y="${186 - h}" text-anchor="middle" font-size="10" fill="var(--ink)">${m.t}</text><text x="${x + w * 0.3}" y="206" text-anchor="middle" font-size="8.5" fill="var(--mut)">${esc(m.n.slice(0, 11))}</text>`; }).join('') + `<polyline fill="none" stroke="var(--cP)" stroke-width="2" points="${top.map((m, i) => `${34 + i * w + w * 0.3},${190 - (m.acu / 100) * 150}`).join(' ')}"/>`; })()}</svg>` + legend([['Responsable CN', 'var(--s1)'], ['SGF', 'var(--cF)'], ['Otro', 'var(--mut)'], ['% acumulado', 'var(--cP)']]);
