      const per = periodo(rs), regs = [...new Set(rs.map((r) => r.reg).filter((x) => x && x !== '—'))], ambito = ((X.S.sup || []).join(' / ') || S.me.supervisor || regs.join(' / ') || 'NACIONAL').toUpperCase(), F = 'Arial', pct = (x) => f1(x), fm = (x) => fN(x), dimK = X.S.idim === 'ger' && T ? 'sup' : X.S.idim, dimN = DIMN(tp)[dimK] || 'Supervisor';
